INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter binären Literalen?', 2, '[{"text": "Direkte Darstellung von Binärdaten", "correct": true, "because": "z.B. 0b1010"}, {"text": "Textdarstellung von Daten", "correct": false, "because": "String-Literale"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit binären Literalen?', 3, '[{"text": "Binärwerte direkt definieren", "correct": true, "because": "Einfache Eingabe"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Kein Sicherheitsfokus"}, {"text": "Speicherplatz sparen", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Formate gehören zu binären Literalen?', 5, '[{"text": "Binär (0b)", "correct": true, "because": "z.B. 0b1010"}, {"text": "Hexadezimal (0x)", "correct": true, "because": "z.B. 0xFF"}, {"text": "Dezimal (10)", "correct": false, "because": "Keine Binärdarstellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Binäre Literale beginnen oft mit 0b. b) Sie sind nur in SQL nutzbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch in anderen Sprachen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei binären Literalen?', 4, '[{"text": "Syntax", "correct": false, "because": "z.B. 0b nötig"}, {"text": "Bitanzahl", "correct": false, "because": "Definiert Wert"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob binäre Literale in Python mit 0b beginnen?', 2, '[{"text": "Ja", "correct": true, "because": "z.B. 0b1010"}, {"text": "Nein", "correct": false, "because": "Standard in Python"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches binäre Literal entspricht dem Dezimalwert 10?', 3, '[{"text": "0b1010", "correct": true, "because": "Binär 1010 = 10"}, {"text": "0b1000", "correct": false, "because": "Binär 1000 = 8"}, {"text": "0b1111", "correct": false, "because": "Binär 1111 = 15"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Verwendung von binären Literalen?', 5, '[{"text": "Korrekte Syntax", "correct": true, "because": "z.B. 0b oder 0x"}, {"text": "Bitweise Operationen", "correct": true, "because": "Häufig genutzt"}, {"text": "Farbcodierung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Binäre Literale sind in vielen Programmiersprachen nutzbar. b) Sie sind nur für Hexadezimalwerte gedacht. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Binärwerte"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei binären Literalen unwichtig?', 4, '[{"text": "Präfix (0b/0x)", "correct": false, "because": "Syntax nötig"}, {"text": "Bitdarstellung", "correct": false, "because": "Definiert Wert"}, {"text": "Schriftart", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein binäres Literal in SQL genutzt werden?', 2, '[{"text": "Ja", "correct": true, "because": "z.B. 0xFF in BLOBs"}, {"text": "Nein", "correct": false, "because": "Unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten binäre Literale für Fachinformatiker?', 4, '[{"text": "Direkte Bitmanipulation", "correct": true, "because": "Effiziente Programmierung"}, {"text": "Lesbare Eingabe", "correct": true, "because": "Klar für Entwickler"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass binäre Literale nur für kleine Werte sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Größe abhängig von Sprache"}, {"text": "Ja", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei binären Literalen?', 3, '[{"text": "Korrekte Syntax", "correct": true, "because": "Erkennung durch Compiler"}, {"text": "Kosten", "correct": false, "because": "Irrelevant"}, {"text": "Ästhetik", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Binäre Literale können Hexadezimal sein. b) Sie sind nur in Hochsprachen nutzbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Assembler"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine falsche Verwendung von binären Literalen?', 5, '[{"text": "Compilerfehler", "correct": true, "because": "Syntaxfehler"}, {"text": "Falsche Werte", "correct": true, "because": "Logikfehler"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker bei binären Literalen?', 3, '[{"text": "Korrekte Implementierung", "correct": true, "because": "Programmierung"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein binäres Literal in einer Datenbank gespeichert werden?', 2, '[{"text": "Ja", "correct": true, "because": "z.B. als BLOB"}, {"text": "Nein", "correct": false, "because": "Unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches binäre Literal entspricht Hexadezimal 0xA?', 4, '[{"text": "0b1010", "correct": true, "because": "0xA = 10 = 0b1010"}, {"text": "0b1111", "correct": false, "because": "0b1111 = 15"}, {"text": "0b1000", "correct": false, "because": "0b1000 = 8"}]');
